import { Component } from '@angular/core';
import { FormBuilder, FormGroup, Validators, ReactiveFormsModule } from '@angular/forms';
import { Router, RouterModule } from '@angular/router';
import { AuthService } from '../auth.service';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, RouterModule],
  templateUrl: './login.component.html',
  // styleUrls: ['./login.component.css'] // Add if you have specific styles
})
export class LoginComponent {
  loginForm: FormGroup;
  loginError: string = '';

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private router: Router
  ) {
    this.loginForm = this.fb.group({
      username: ['', Validators.required],
      password: ['', Validators.required]
    });
  }

  onSubmit(): void {
    if (this.loginForm.valid) {
      const username = this.loginForm.value.username;
      const password = this.loginForm.value.password;
      if (this.authService.login(username, password)) {
        const redirectUrl = this.authService.redirectUrl ? this.authService.redirectUrl : '/';
        this.router.navigate([redirectUrl]);
        this.authService.redirectUrl = null; // Clear redirect URL
      } else {
        this.loginError = 'Invalid username or password.';
      }
    }
  }
}
<div class="flex items-center justify-center min-h-screen bg-gray-100">
  <div class="px-8 py-6 mt-4 text-left bg-white shadow-lg rounded-lg">
    <h3 class="text-2xl font-bold text-center text-[#eb6c28]">Login to your account</h3>
    <form [formGroup]="loginForm" (ngSubmit)="onSubmit()">
      <div class="mt-4">
        <div>
          <label class="block" for="username">Username</label>
          <input type="text" placeholder="Username" formControlName="username"
                 class="w-full px-4 py-2 mt-2 border rounded-md focus:outline-none focus:ring-1 focus:ring-[#eb6c28]">
          <div *ngIf="loginForm.get('username')?.invalid && (loginForm.get('username')?.dirty || loginForm.get('username')?.touched)"
               class="text-red-500 text-sm mt-1">
            Username is required.
          </div>
        </div>
        <div class="mt-4">
          <label class="block" for="password">Password</label>
          <input type="password" placeholder="Password" formControlName="password"
                 class="w-full px-4 py-2 mt-2 border rounded-md focus:outline-none focus:ring-1 focus:ring-[#eb6c28]">
          <div *ngIf="loginForm.get('password')?.invalid && (loginForm.get('password')?.dirty || loginForm.get('password')?.touched)"
               class="text-red-500 text-sm mt-1">
            Password is required.
          </div>
        </div>
        <div *ngIf="loginError" class="text-red-500 text-sm mt-2">
          {{ loginError }}
        </div>
        <div class="flex items-baseline justify-between">
          <button class="px-6 py-2 mt-4 text-white bg-[#eb6c28] rounded-lg hover:bg-[#d35400]" type="submit" [disabled]="loginForm.invalid">Login</button>
          <a href="#" class="text-sm text-[#eb6c28] hover:underline">Forgot password?</a>
        </div>
      </div>
    </form>
  </div>
</div>
